-- Athena views for the DuckDB models in transform/sql.
-- Generated by: python -m transform.athena_sql
-- Catalog prefix: pix
-- Matches the Glue databases from infra/terraform (catalog_prefix).
-- Raw tables are external tables owned by Terraform.
-- Run this script in the pix workgroup after apply. Do not edit by hand.

CREATE DATABASE IF NOT EXISTS pix_raw;
CREATE DATABASE IF NOT EXISTS pix_seeds;
CREATE DATABASE IF NOT EXISTS pix_staging;
CREATE DATABASE IF NOT EXISTS pix_intermediate;
CREATE DATABASE IF NOT EXISTS pix_marts;
CREATE DATABASE IF NOT EXISTS pix_checks;

CREATE OR REPLACE VIEW pix_seeds.seed_faixa_idade AS
-- Age-band strings published by Olinda (docs/spike-bcb.md).
-- The rotulo is the API text. ordem is for charts, youngest first,
-- with the two non-age values last.

select
    codigo,
    rotulo,
    ordem,
    fonte
from (
    values
    ('até 19 anos', 'até 19 anos', 1, 'olinda-texto'),
    ('entre 20 e 29 anos', 'entre 20 e 29 anos', 2, 'olinda-texto'),
    ('entre 30 e 39 anos', 'entre 30 e 39 anos', 3, 'olinda-texto'),
    ('entre 40 e 49 anos', 'entre 40 e 49 anos', 4, 'olinda-texto'),
    ('entre 50 e 59 anos', 'entre 50 e 59 anos', 5, 'olinda-texto'),
    ('mais de 60 anos', 'mais de 60 anos', 6, 'olinda-texto'),
    ('Nao se aplica', 'Nao se aplica', 7, 'olinda-texto'),
    ('Nao informado', 'Nao informado', 8, 'olinda-texto')
) as faixa_idade(codigo, rotulo, ordem, fonte);

CREATE OR REPLACE VIEW pix_seeds.seed_finalidade AS
-- FINALIDADE values published by Olinda (docs/spike-bcb.md).
-- The strings are already labels. Only "Nao disponivel" is accented here.

select
    codigo,
    rotulo,
    fonte
from (
    values
    ('Pix', 'Pix', 'olinda-texto'),
    ('Pix Saque', 'Pix Saque', 'olinda-texto'),
    ('Pix Troco', 'Pix Troco', 'olinda-texto'),
    ('Nao disponivel', 'Não disponível', 'olinda-texto')
) as finalidade(codigo, rotulo, fonte);

CREATE OR REPLACE VIEW pix_seeds.seed_forma_iniciacao AS
-- FORMAINICIACAO codes from the 202610 extract (docs/spike-bcb.md).
-- DICT, MANU, INIC, QRES, QRDN, and AUTO are the "Tipo de Iniciação"
-- columns in Banco Central do Brasil, Manual de Padrões para Iniciação
-- do Pix, versão 2.10.0, seção 3.2.
-- APDN is the catalog domain for Pix por aproximação (Fórum Pix, 24ª
-- reunião plenária; Manual seção 3.4 describes the NFC flow).
-- APES is in the extract. The label treats it as the static counterpart
-- of APDN, parallel to QRES/QRDN. That gloss is not a BCB sentence, so
-- publicado is false.
-- "Nao disponivel" is the API's own text, not a manual code.

select
    codigo,
    rotulo,
    publicado,
    fonte
from (
    values
    ('DICT', 'Chave Pix', true, 'bcb-manual-iniciacao-pix-2.10'),
    ('MANU', 'Inserção manual dos dados', true, 'bcb-manual-iniciacao-pix-2.10'),
    ('INIC', 'Serviço de iniciação de transação de pagamento', true, 'bcb-manual-iniciacao-pix-2.10'),
    ('QRES', 'QR Code estático', true, 'bcb-manual-iniciacao-pix-2.10'),
    ('QRDN', 'QR Code dinâmico', true, 'bcb-manual-iniciacao-pix-2.10'),
    ('AUTO', 'Pix Automático', true, 'bcb-manual-iniciacao-pix-2.10'),
    ('APDN', 'Pix por aproximação', true, 'bcb-forum-pix-dominio-apdn'),
    ('APES', 'Pix por aproximação estático', false, 'inferido-par-qres-qrdn'),
    ('Nao disponivel', 'Não disponível', true, 'olinda-texto')
) as forma_iniciacao(codigo, rotulo, publicado, fonte);

CREATE OR REPLACE VIEW pix_seeds.seed_natureza AS
-- Nine NATUREZA codes observed in the full 202610 extract
-- (docs/spike-bcb.md). First letter is the payer, second is the receiver:
-- P pessoa física, B pessoa jurídica, G governo.
--
-- P2P, P2B, B2P, and B2B are the footnote in Banco Central do Brasil,
-- Relatório Anual do SPI 2025.
-- P2G is named in Relatório de Gestão do Pix 2023-2025
-- ("person to government"; the report spells government with a typo).
-- G2P, B2G, G2B, and G2G use that same convention. The Gestão report
-- groups those flows as Governo and does not publish a separate gloss,
-- so publicado is false for them.

select
    codigo,
    rotulo,
    descricao,
    publicado,
    fonte
from (
    values
    (
        'P2P',
        'Pessoa física para pessoa física',
        'Pagador pessoa física, recebedor pessoa física',
        true,
        'bcb-relatorio-anual-spi-2025'
    ),
    (
        'P2B',
        'Pessoa física para pessoa jurídica',
        'Pagador pessoa física, recebedor pessoa jurídica',
        true,
        'bcb-relatorio-anual-spi-2025'
    ),
    (
        'B2P',
        'Pessoa jurídica para pessoa física',
        'Pagador pessoa jurídica, recebedor pessoa física',
        true,
        'bcb-relatorio-anual-spi-2025'
    ),
    (
        'B2B',
        'Pessoa jurídica para pessoa jurídica',
        'Pagador pessoa jurídica, recebedor pessoa jurídica',
        true,
        'bcb-relatorio-anual-spi-2025'
    ),
    (
        'P2G',
        'Pessoa física para o governo',
        'Pagador pessoa física, recebedor governo',
        true,
        'bcb-relatorio-gestao-pix-2023-2025'
    ),
    (
        'G2P',
        'Governo para pessoa física',
        'Pagador governo, recebedor pessoa física',
        false,
        'convencao-pbg'
    ),
    (
        'B2G',
        'Pessoa jurídica para o governo',
        'Pagador pessoa jurídica, recebedor governo',
        false,
        'convencao-pbg'
    ),
    (
        'G2B',
        'Governo para pessoa jurídica',
        'Pagador governo, recebedor pessoa jurídica',
        false,
        'convencao-pbg'
    ),
    (
        'G2G',
        'Governo para governo',
        'Pagador governo, recebedor governo',
        false,
        'convencao-pbg'
    )
) as natureza(codigo, rotulo, descricao, publicado, fonte);

CREATE OR REPLACE VIEW pix_seeds.seed_regiao AS
-- Macro-regions as EstatisticasTransacoesPix spells them, plus the
-- published "Nao informado" value. Siglas match TransacoesPixPorMunicipio
-- and the IBGE five-region division.

select
    codigo,
    rotulo,
    sigla,
    fonte
from (
    values
    ('NORTE', 'Norte', 'N', 'ibge-grandes-regioes'),
    ('NORDESTE', 'Nordeste', 'NE', 'ibge-grandes-regioes'),
    ('SUDESTE', 'Sudeste', 'SE', 'ibge-grandes-regioes'),
    ('SUL', 'Sul', 'S', 'ibge-grandes-regioes'),
    ('CENTRO-OESTE', 'Centro-Oeste', 'CO', 'ibge-grandes-regioes'),
    ('Nao informado', 'Não informado', cast(null as varchar), 'olinda-texto')
) as regiao(codigo, rotulo, sigla, fonte);

CREATE OR REPLACE VIEW pix_seeds.seed_tipo_chave AS
-- TipoChave values in the ChavesPix snapshot of 2026-10-31
-- (docs/spike-bcb.md). The API already returns readable labels.
-- ordem is a stable chart order, not a volume ranking.

select
    codigo,
    rotulo,
    ordem,
    fonte
from (
    values
    ('CPF', 'CPF', 1, 'olinda-chavespix'),
    ('CNPJ', 'CNPJ', 2, 'olinda-chavespix'),
    ('Celular', 'Celular', 3, 'olinda-chavespix'),
    ('e-mail', 'E-mail', 4, 'olinda-chavespix'),
    ('Aleatória', 'Aleatória', 5, 'olinda-chavespix')
) as tipo_chave(codigo, rotulo, ordem, fonte);

CREATE OR REPLACE VIEW pix_seeds.seed_tipo_pessoa AS
-- PAG_PFPJ, REC_PFPJ, and NaturezaUsuario.
-- PF and PJ are the values in the extract (docs/spike-bcb.md).

select
    codigo,
    rotulo,
    fonte
from (
    values
    ('PF', 'Pessoa física', 'olinda-texto'),
    ('PJ', 'Pessoa jurídica', 'olinda-texto')
) as tipo_pessoa(codigo, rotulo, fonte);

CREATE OR REPLACE VIEW pix_seeds.seed_uf AS
-- IBGE state codes (UF) and the five macro-regions.
-- uf_ibge 0 is the sentinel for the PIX "Não informado" bucket. IBGE
-- does not assign 0 to a state. Source: IBGE, códigos das unidades da
-- federação and the divisão regional do Brasil.

select
    uf_ibge,
    sigla,
    nome,
    sigla_regiao,
    regiao_nome
from (
    values
    (11, 'RO', 'Rondônia', 'N', 'Norte'),
    (12, 'AC', 'Acre', 'N', 'Norte'),
    (13, 'AM', 'Amazonas', 'N', 'Norte'),
    (14, 'RR', 'Roraima', 'N', 'Norte'),
    (15, 'PA', 'Pará', 'N', 'Norte'),
    (16, 'AP', 'Amapá', 'N', 'Norte'),
    (17, 'TO', 'Tocantins', 'N', 'Norte'),
    (21, 'MA', 'Maranhão', 'NE', 'Nordeste'),
    (22, 'PI', 'Piauí', 'NE', 'Nordeste'),
    (23, 'CE', 'Ceará', 'NE', 'Nordeste'),
    (24, 'RN', 'Rio Grande do Norte', 'NE', 'Nordeste'),
    (25, 'PB', 'Paraíba', 'NE', 'Nordeste'),
    (26, 'PE', 'Pernambuco', 'NE', 'Nordeste'),
    (27, 'AL', 'Alagoas', 'NE', 'Nordeste'),
    (28, 'SE', 'Sergipe', 'NE', 'Nordeste'),
    (29, 'BA', 'Bahia', 'NE', 'Nordeste'),
    (31, 'MG', 'Minas Gerais', 'SE', 'Sudeste'),
    (32, 'ES', 'Espírito Santo', 'SE', 'Sudeste'),
    (33, 'RJ', 'Rio de Janeiro', 'SE', 'Sudeste'),
    (35, 'SP', 'São Paulo', 'SE', 'Sudeste'),
    (41, 'PR', 'Paraná', 'S', 'Sul'),
    (42, 'SC', 'Santa Catarina', 'S', 'Sul'),
    (43, 'RS', 'Rio Grande do Sul', 'S', 'Sul'),
    (50, 'MS', 'Mato Grosso do Sul', 'CO', 'Centro-Oeste'),
    (51, 'MT', 'Mato Grosso', 'CO', 'Centro-Oeste'),
    (52, 'GO', 'Goiás', 'CO', 'Centro-Oeste'),
    (53, 'DF', 'Distrito Federal', 'CO', 'Centro-Oeste'),
    (0, cast(null as varchar), 'Não informado', cast(null as varchar), 'Não informado')
) as uf(uf_ibge, sigla, nome, sigla_regiao, regiao_nome);

CREATE OR REPLACE VIEW pix_staging.stg_app_pix_disputes AS
-- CDC log for simulated MED disputes opened against an operational transaction.
-- resolved_at is null while the dispute is open.

select
    op,
    lsn,
    lsn_ord,
    cast(commit_ts as timestamp) as commit_ts,
    pk,
    id,
    transaction_id,
    reason,
    status,
    cast(opened_at as timestamp) as opened_at,
    cast(resolved_at as timestamp) as resolved_at,
    cast(created_at as timestamp) as created_at,
    cast(updated_at as timestamp) as updated_at
from pix_raw.app_pix_disputes;

CREATE OR REPLACE VIEW pix_staging.stg_app_pix_keys AS
-- CDC log for the operational PIX key registry.
-- The sink writes every column as text. Casts live here, same as the
-- Olinda staging models. commit_ts is UTC. lsn_ord is fixed-width hex so
-- the latest change follows the WAL rather than the clock.

select
    op,
    lsn,
    lsn_ord,
    cast(commit_ts as timestamp) as commit_ts,
    pk,
    id,
    key_type,
    key_value,
    person_type,
    lpad(ispb, 8, '0') as ispb,
    cast(municipio_ibge as integer) as municipio_ibge,
    status,
    cast(created_at as timestamp) as created_at,
    cast(updated_at as timestamp) as updated_at
from pix_raw.app_pix_keys;

CREATE OR REPLACE VIEW pix_staging.stg_app_pix_transactions AS
-- CDC log for operational PIX transactions.
-- amount is the text pgoutput emitted (for example 10.50). direction is
-- inbound or outbound from the simulated PSP's point of view.

select
    op,
    lsn,
    lsn_ord,
    cast(commit_ts as timestamp) as commit_ts,
    pk,
    id,
    end_to_end_id,
    cast(amount as decimal(18, 2)) as amount,
    lpad(payer_ispb, 8, '0') as payer_ispb,
    lpad(receiver_ispb, 8, '0') as receiver_ispb,
    cast(municipio_ibge as integer) as municipio_ibge,
    forma_iniciacao,
    direction,
    status,
    cast(occurred_at as timestamp) as occurred_at,
    cast(created_at as timestamp) as created_at,
    cast(updated_at as timestamp) as updated_at
from pix_raw.app_pix_transactions;

CREATE OR REPLACE VIEW pix_staging.stg_chaves_pix AS
-- Typed, renamed projection of ChavesPix.
-- ISPB stays text so leading zeros survive. The month key is derived
-- from the snapshot date in pix_intermediate.

select
    cast("Data" as date) as data_referencia,
    trim("ISPB") as ispb,
    trim("Nome") as nome,
    trim("NaturezaUsuario") as natureza_usuario,
    trim("TipoChave") as tipo_chave,
    cast("qtdChaves" as bigint) as quantidade_chaves,
    trim("Segmento") as segmento
from pix_raw.chaves_pix;

CREATE OR REPLACE VIEW pix_staging.stg_estatisticas_transacoes_pix AS
-- Typed, renamed projection of EstatisticasTransacoesPix.
-- Quoted identifiers are the physical Olinda names. Every later model
-- uses the snake_case columns. Measures stay DECIMAL(38, 8), the scale
-- the raw writer stores.

select
    cast("AnoMes" as integer) as ano_mes,
    trim("PAG_PFPJ") as pagador_tipo_pessoa,
    trim("REC_PFPJ") as recebedor_tipo_pessoa,
    trim("PAG_REGIAO") as pagador_regiao,
    trim("REC_REGIAO") as recebedor_regiao,
    trim("PAG_IDADE") as pagador_faixa_idade,
    trim("REC_IDADE") as recebedor_faixa_idade,
    trim("FORMAINICIACAO") as forma_iniciacao,
    trim("NATUREZA") as natureza,
    trim("FINALIDADE") as finalidade,
    cast("VALOR" as decimal(38, 8)) as valor,
    cast("QUANTIDADE" as decimal(38, 8)) as quantidade
from pix_raw.estatisticas_transacoes_pix;

CREATE OR REPLACE VIEW pix_staging.stg_transacoes_pix_municipio AS
-- Typed, renamed projection of TransacoesPixPorMunicipio.
-- Null IBGE codes are preserved. The N/D bucket is labeled downstream
-- and is not dropped here.

select
    cast("AnoMes" as integer) as ano_mes,
    cast("Municipio_Ibge" as integer) as municipio_ibge,
    trim("Municipio") as municipio,
    cast("Estado_Ibge" as integer) as uf_ibge,
    trim("Estado") as uf_nome,
    trim("Sigla_Regiao") as sigla_regiao,
    trim("Regiao") as regiao_nome,
    cast("VL_PagadorPF" as decimal(38, 8)) as valor_pagador_pf,
    cast("QT_PagadorPF" as decimal(38, 8)) as quantidade_pagador_pf,
    cast("VL_PagadorPJ" as decimal(38, 8)) as valor_pagador_pj,
    cast("QT_PagadorPJ" as decimal(38, 8)) as quantidade_pagador_pj,
    cast("VL_RecebedorPF" as decimal(38, 8)) as valor_recebedor_pf,
    cast("QT_RecebedorPF" as decimal(38, 8)) as quantidade_recebedor_pf,
    cast("VL_RecebedorPJ" as decimal(38, 8)) as valor_recebedor_pj,
    cast("QT_RecebedorPJ" as decimal(38, 8)) as quantidade_recebedor_pj,
    cast("QT_PES_PagadorPF" as decimal(38, 8)) as quantidade_pessoas_pagador_pf,
    cast("QT_PES_PagadorPJ" as decimal(38, 8)) as quantidade_pessoas_pagador_pj,
    cast("QT_PES_RecebedorPF" as decimal(38, 8)) as quantidade_pessoas_recebedor_pf,
    cast("QT_PES_RecebedorPJ" as decimal(38, 8)) as quantidade_pessoas_recebedor_pj
from pix_raw.transacoes_pix_municipio;

CREATE OR REPLACE VIEW pix_intermediate.int_app_pix_disputes AS
-- Latest CDC image of each dispute, including deletes.

select
    op,
    lsn,
    lsn_ord,
    commit_ts,
    id,
    transaction_id,
    reason,
    status,
    opened_at,
    resolved_at,
    created_at,
    updated_at
from (
    select
        staged.*,
        row_number() over (
            partition by id
            order by lsn_ord desc
        ) as change_rank
    from pix_staging.stg_app_pix_disputes as staged
) ranked
where change_rank = 1;

CREATE OR REPLACE VIEW pix_intermediate.int_app_pix_keys AS
-- Latest CDC image of each PIX key, including deletes.
-- The consumer already collapses a transaction to one event per id.
-- Two commits for the same id are ordered by lsn_ord, not by file order
-- and not by commit_ts.

select
    op,
    lsn,
    lsn_ord,
    commit_ts,
    id,
    key_type,
    key_value,
    person_type,
    ispb,
    municipio_ibge,
    status,
    created_at,
    updated_at
from (
    select
        staged.*,
        row_number() over (
            partition by id
            order by lsn_ord desc
        ) as change_rank
    from pix_staging.stg_app_pix_keys as staged
) ranked
where change_rank = 1;

CREATE OR REPLACE VIEW pix_intermediate.int_app_pix_transactions AS
-- Latest CDC image of each operational PIX transaction, including deletes.

select
    op,
    lsn,
    lsn_ord,
    commit_ts,
    id,
    end_to_end_id,
    amount,
    payer_ispb,
    receiver_ispb,
    municipio_ibge,
    forma_iniciacao,
    direction,
    status,
    occurred_at,
    created_at,
    updated_at
from (
    select
        staged.*,
        row_number() over (
            partition by id
            order by lsn_ord desc
        ) as change_rank
    from pix_staging.stg_app_pix_transactions as staged
) ranked
where change_rank = 1;

CREATE OR REPLACE VIEW pix_intermediate.int_chaves_pix AS
-- Key stock for one snapshot month.
-- ChavesPix dates in the extract are the last calendar day of the month.
-- ano_mes is that month. ISPB is left-padded to 8 characters; a value
-- that is already 8 characters is unchanged, including leading zeros.

select
    data_referencia,
    cast(substr(cast(data_referencia as varchar), 1, 4) as integer) * 100
        + cast(substr(cast(data_referencia as varchar), 6, 2) as integer) as ano_mes,
    lpad(ispb, 8, '0') as ispb,
    nome,
    natureza_usuario,
    tipo_chave,
    quantidade_chaves,
    segmento
from pix_staging.stg_chaves_pix;

CREATE OR REPLACE VIEW pix_intermediate.int_transacoes_mensal AS
-- Conformed monthly transaction grain.
-- One row for each raw combination of month, payer and receiver person
-- type, region, age band, initiation form, natureza, and finalidade.
-- Nothing is filtered: a new code stays on the row and is picked up by
-- the matching dimension.

select
    ano_mes,
    pagador_tipo_pessoa,
    recebedor_tipo_pessoa,
    pagador_regiao,
    recebedor_regiao,
    pagador_faixa_idade,
    recebedor_faixa_idade,
    forma_iniciacao,
    natureza,
    finalidade,
    valor,
    quantidade
from pix_staging.stg_estatisticas_transacoes_pix;

CREATE OR REPLACE VIEW pix_intermediate.int_transacoes_municipio AS
-- Municipality month, with the published N/D bucket kept.
-- municipio_ibge 0 and uf_ibge 0 mean "Não informado". IBGE does not
-- assign 0. The raw row has null codes and Municipio = 'N/D' (see
-- docs/spike-bcb.md). A row named N/D is mapped the same way even if a
-- code appears later, so that label cannot become a city.

select
    ano_mes,
    case
        when municipio_ibge is null or upper(municipio) in ('N/D', 'ND') then 0
        else municipio_ibge
    end as municipio_ibge,
    case
        when municipio_ibge is null or upper(municipio) in ('N/D', 'ND') then 'Não informado'
        else municipio
    end as nome,
    municipio as nome_fonte,
    case
        when municipio_ibge is null or upper(municipio) in ('N/D', 'ND') then 0
        else uf_ibge
    end as uf_ibge,
    uf_nome as uf_nome_fonte,
    case
        when municipio_ibge is null or upper(municipio) in ('N/D', 'ND') then cast(null as varchar)
        else sigla_regiao
    end as sigla_regiao,
    regiao_nome as regiao_nome_fonte,
    valor_pagador_pf,
    quantidade_pagador_pf,
    valor_pagador_pj,
    quantidade_pagador_pj,
    valor_recebedor_pf,
    quantidade_recebedor_pf,
    valor_recebedor_pj,
    quantidade_recebedor_pj,
    quantidade_pessoas_pagador_pf,
    quantidade_pessoas_pagador_pj,
    quantidade_pessoas_recebedor_pf,
    quantidade_pessoas_recebedor_pj
from pix_staging.stg_transacoes_pix_municipio;

CREATE OR REPLACE VIEW pix_marts.cur_pix_dispute AS
-- Current simulated MED disputes.
-- Grain: id. An accepted or rejected dispute stays until it is deleted.
-- transaction_id points at cur_pix_transaction. A dispute whose payment
-- was deleted fails the referential check on purpose.

select
    id,
    transaction_id,
    reason,
    status,
    opened_at,
    resolved_at,
    created_at,
    updated_at,
    lsn,
    commit_ts
from pix_intermediate.int_app_pix_disputes
where op <> 'delete';

CREATE OR REPLACE VIEW pix_marts.cur_pix_key AS
-- Current PIX key registry.
-- Grain: id. The latest CDC image, with deletes removed.
-- ispb joins to dim_instituicao. municipio_ibge joins to dim_municipio.
-- lsn is the commit that produced this image, not a business timestamp.

select
    id,
    key_type,
    key_value,
    person_type,
    ispb,
    municipio_ibge,
    status,
    created_at,
    updated_at,
    lsn,
    commit_ts
from pix_intermediate.int_app_pix_keys
where op <> 'delete';

CREATE OR REPLACE VIEW pix_marts.cur_pix_transaction AS
-- Current operational PIX transactions.
-- Grain: id. Deletes are removed. A refunded payment stays, with that status.
-- payer_ispb and receiver_ispb join to dim_instituicao.
-- municipio_ibge joins to dim_municipio. forma_iniciacao joins to
-- dim_forma_iniciacao.

select
    id,
    end_to_end_id,
    amount,
    payer_ispb,
    receiver_ispb,
    municipio_ibge,
    forma_iniciacao,
    direction,
    status,
    occurred_at,
    created_at,
    updated_at,
    lsn,
    commit_ts
from pix_intermediate.int_app_pix_transactions
where op <> 'delete';

CREATE OR REPLACE VIEW pix_marts.dim_faixa_idade AS
-- One row per age band as Olinda spells it.
-- Grain: codigo. ordem is null for a band that is not in the seed.

with observed as (
    select distinct faixa as codigo
    from (
        select pagador_faixa_idade as faixa
        from pix_intermediate.int_transacoes_mensal
        union
        select recebedor_faixa_idade as faixa
        from pix_intermediate.int_transacoes_mensal
    ) as bands
    where faixa is not null
)
select
    coalesce(seed.codigo, observed.codigo) as codigo,
    coalesce(seed.rotulo, observed.codigo) as rotulo,
    seed.ordem as ordem,
    coalesce(seed.fonte, 'raw') as fonte
from pix_seeds.seed_faixa_idade as seed
full outer join observed
    on seed.codigo = observed.codigo;

CREATE OR REPLACE VIEW pix_marts.dim_finalidade AS
-- One row per finalidade, including "Nao disponivel".
-- Grain: codigo.

with observed as (
    select distinct finalidade as codigo
    from pix_intermediate.int_transacoes_mensal
    where finalidade is not null
)
select
    coalesce(seed.codigo, observed.codigo) as codigo,
    coalesce(seed.rotulo, observed.codigo) as rotulo,
    coalesce(seed.fonte, 'raw') as fonte
from pix_seeds.seed_finalidade as seed
full outer join observed
    on seed.codigo = observed.codigo;

CREATE OR REPLACE VIEW pix_marts.dim_forma_iniciacao AS
-- One row per initiation-form code, including "Nao disponivel".
-- Unknown codes from the extract are kept with rotulo = codigo.
-- Grain: codigo.

with observed as (
    select distinct forma_iniciacao as codigo
    from pix_intermediate.int_transacoes_mensal
    where forma_iniciacao is not null
)
select
    coalesce(seed.codigo, observed.codigo) as codigo,
    coalesce(seed.rotulo, observed.codigo) as rotulo,
    coalesce(seed.publicado, false) as publicado,
    coalesce(seed.fonte, 'raw') as fonte
from pix_seeds.seed_forma_iniciacao as seed
full outer join observed
    on seed.codigo = observed.codigo;

CREATE OR REPLACE VIEW pix_marts.dim_instituicao AS
-- One row per ISPB. Type 1: nome and segmento come from the latest
-- snapshot month, so a rename does not keep history. The fact still has
-- one row per month. ChavesPix is a stock of keys by institution, not
-- payment volume. The transaction extracts have no ISPB.
-- Grain: ispb.

with ranked as (
    select
        ispb,
        nome,
        segmento,
        ano_mes,
        row_number() over (
            partition by ispb
            order by ano_mes desc, data_referencia desc
        ) as rn
    from pix_intermediate.int_chaves_pix
)
select
    ispb,
    nome,
    segmento,
    ano_mes as ano_mes_referencia
from ranked
where rn = 1;

CREATE OR REPLACE VIEW pix_marts.dim_municipio AS
-- One row per municipality, including municipio_ibge 0 ("Não informado").
-- Attributes come from the latest month in the extract. UF sigla and the
-- display name of the state come from the IBGE seed when the code matches.
-- The raw municipality name is kept (Olinda publishes it in uppercase).
-- Grain: municipio_ibge.

with ranked as (
    select
        municipio_ibge,
        nome,
        nome_fonte,
        uf_ibge,
        uf_nome_fonte,
        sigla_regiao,
        regiao_nome_fonte,
        row_number() over (
            partition by municipio_ibge
            order by ano_mes desc
        ) as rn
    from pix_intermediate.int_transacoes_municipio
)
select
    ranked.municipio_ibge,
    ranked.nome,
    ranked.nome_fonte,
    ranked.uf_ibge,
    uf.sigla as uf_sigla,
    coalesce(uf.nome, ranked.uf_nome_fonte) as uf_nome,
    coalesce(uf.sigla_regiao, ranked.sigla_regiao) as sigla_regiao,
    coalesce(uf.regiao_nome, ranked.regiao_nome_fonte) as regiao_nome
from ranked
left join pix_seeds.seed_uf as uf
    on ranked.uf_ibge = uf.uf_ibge
where ranked.rn = 1;

CREATE OR REPLACE VIEW pix_marts.dim_natureza AS
-- One row per natureza code.
-- Seed labels, plus any code that appears in the extract and is missing
-- from the seed. An unknown code keeps the raw value as rotulo and
-- publicado = false, so a tenth code is not dropped.
-- Grain: codigo.

with observed as (
    select distinct natureza as codigo
    from pix_intermediate.int_transacoes_mensal
    where natureza is not null
)
select
    coalesce(seed.codigo, observed.codigo) as codigo,
    coalesce(seed.rotulo, observed.codigo) as rotulo,
    seed.descricao as descricao,
    coalesce(seed.publicado, false) as publicado,
    coalesce(seed.fonte, 'raw') as fonte
from pix_seeds.seed_natureza as seed
full outer join observed
    on seed.codigo = observed.codigo;

CREATE OR REPLACE VIEW pix_marts.dim_regiao AS
-- Macro-region of the payer or the receiver on the national extract.
-- The key is the raw string (NORDESTE, "Nao informado", ...), so the fact
-- joins without a translation table. Grain: codigo.

with observed as (
    select distinct regiao as codigo
    from (
        select pagador_regiao as regiao
        from pix_intermediate.int_transacoes_mensal
        union
        select recebedor_regiao as regiao
        from pix_intermediate.int_transacoes_mensal
    ) as regions
    where regiao is not null
)
select
    coalesce(seed.codigo, observed.codigo) as codigo,
    coalesce(seed.rotulo, observed.codigo) as rotulo,
    seed.sigla as sigla,
    coalesce(seed.fonte, 'raw') as fonte
from pix_seeds.seed_regiao as seed
full outer join observed
    on seed.codigo = observed.codigo;

CREATE OR REPLACE VIEW pix_marts.dim_tempo AS
-- One row per AnoMes present in any raw entity.
-- The series is monthly. data_inicio is the first day and data_fim is the
-- last day, including 29 February in a leap year. There is no day grain.
-- Grain: ano_mes (YYYYMM).

with months as (
    select ano_mes
    from pix_intermediate.int_transacoes_mensal
    union
    select ano_mes
    from pix_intermediate.int_transacoes_municipio
    union
    select ano_mes
    from pix_intermediate.int_chaves_pix
),
parts as (
    select
        ano_mes,
        cast(substr(lpad(cast(ano_mes as varchar), 6, '0'), 1, 4) as integer) as ano,
        cast(substr(lpad(cast(ano_mes as varchar), 6, '0'), 5, 2) as integer) as mes
    from months
)
select
    ano_mes,
    ano,
    mes,
    cast(floor((mes - 1) / 3) as integer) + 1 as trimestre,
    cast(
        concat(cast(ano as varchar), '-', lpad(cast(mes as varchar), 2, '0'), '-01') as date
    ) as data_inicio,
    cast(
        concat(
            cast(ano as varchar),
            '-',
            lpad(cast(mes as varchar), 2, '0'),
            '-',
            case
                when mes in (1, 3, 5, 7, 8, 10, 12) then '31'
                when mes in (4, 6, 9, 11) then '30'
                when mes = 2 and (
                    ano % 400 = 0 or (ano % 4 = 0 and ano % 100 <> 0)
                ) then '29'
                else '28'
            end
        ) as date
    ) as data_fim,
    case mes
        when 1 then 'Janeiro'
        when 2 then 'Fevereiro'
        when 3 then 'Março'
        when 4 then 'Abril'
        when 5 then 'Maio'
        when 6 then 'Junho'
        when 7 then 'Julho'
        when 8 then 'Agosto'
        when 9 then 'Setembro'
        when 10 then 'Outubro'
        when 11 then 'Novembro'
        when 12 then 'Dezembro'
    end as nome_mes,
    concat(cast(ano as varchar), '-', lpad(cast(mes as varchar), 2, '0')) as rotulo
from parts;

CREATE OR REPLACE VIEW pix_marts.dim_tipo_chave AS
-- PIX key type. The key is the TipoChave string Olinda returns.
-- Grain: codigo.

with observed as (
    select distinct tipo_chave as codigo
    from pix_intermediate.int_chaves_pix
    where tipo_chave is not null
)
select
    coalesce(seed.codigo, observed.codigo) as codigo,
    coalesce(seed.rotulo, observed.codigo) as rotulo,
    seed.ordem as ordem,
    coalesce(seed.fonte, 'raw') as fonte
from pix_seeds.seed_tipo_chave as seed
full outer join observed
    on seed.codigo = observed.codigo;

CREATE OR REPLACE VIEW pix_marts.dim_tipo_pessoa AS
-- Pessoa física / pessoa jurídica. Used by payer, receiver, and key holder.
-- Grain: codigo.

with observed as (
    select distinct codigo
    from (
        select pagador_tipo_pessoa as codigo
        from pix_intermediate.int_transacoes_mensal
        union
        select recebedor_tipo_pessoa as codigo
        from pix_intermediate.int_transacoes_mensal
        union
        select natureza_usuario as codigo
        from pix_intermediate.int_chaves_pix
    ) as codes
    where codigo is not null
)
select
    coalesce(seed.codigo, observed.codigo) as codigo,
    coalesce(seed.rotulo, observed.codigo) as rotulo,
    coalesce(seed.fonte, 'raw') as fonte
from pix_seeds.seed_tipo_pessoa as seed
full outer join observed
    on seed.codigo = observed.codigo;

CREATE OR REPLACE VIEW pix_marts.fct_chaves_pix AS
-- Stock of active PIX keys.
-- Grain: ano_mes, ispb, natureza_usuario, tipo_chave.
-- One row is the key count for that institution, person type, and key
-- type on the snapshot date (the last day of the month in the extract).
-- This is not a flow and not payment volume. Summing quantidade_chaves
-- across months recounts the same keys. Summing across key types on one
-- snapshot is the institution's key stock for that month.

select
    ano_mes,
    data_referencia,
    ispb,
    natureza_usuario,
    tipo_chave,
    quantidade_chaves
from pix_intermediate.int_chaves_pix;

CREATE OR REPLACE VIEW pix_marts.fct_transacoes_mensal AS
-- Monthly PIX transactions settled in SPI, at the published grain.
-- Grain: ano_mes, pagador_tipo_pessoa, recebedor_tipo_pessoa,
-- pagador_regiao, recebedor_regiao, pagador_faixa_idade,
-- recebedor_faixa_idade, forma_iniciacao, natureza, finalidade.
-- valor and quantidade add across this grain to the national total for
-- the month. Payer and receiver are columns of the same row, so summing
-- valor does not double-count. There is no ISPB and no day. Banco Central
-- do Brasil describes this resource as quantity and value settled in the
-- month, excluding PIX settled on the participant's own books (not sent
-- to SPI). The payload has no column for that exclusion.

select
    ano_mes,
    pagador_tipo_pessoa,
    recebedor_tipo_pessoa,
    pagador_regiao,
    recebedor_regiao,
    pagador_faixa_idade,
    recebedor_faixa_idade,
    forma_iniciacao,
    natureza,
    finalidade,
    valor,
    quantidade
from pix_intermediate.int_transacoes_mensal;

CREATE OR REPLACE VIEW pix_marts.fct_transacoes_municipio AS
-- PIX value and counts by municipality and month, including the
-- "Não informado" member (municipio_ibge 0).
-- Grain: ano_mes, municipio_ibge.
-- valor_enviado is what payers in the municipality sent (PF + PJ).
-- valor_recebido is what receivers in the municipality got. Do not add
-- the two sides: a payment is counted once as sent and once as received,
-- often in different municipalities. quantidade_pessoas_* are distinct
-- people in that municipality-month. They are not additive across months,
-- and the sum across municipalities is not a national distinct count.

select
    ano_mes,
    municipio_ibge,
    valor_pagador_pf,
    quantidade_pagador_pf,
    valor_pagador_pj,
    quantidade_pagador_pj,
    valor_recebedor_pf,
    quantidade_recebedor_pf,
    valor_recebedor_pj,
    quantidade_recebedor_pj,
    quantidade_pessoas_pagador_pf,
    quantidade_pessoas_pagador_pj,
    quantidade_pessoas_recebedor_pf,
    quantidade_pessoas_recebedor_pj,
    valor_pagador_pf + valor_pagador_pj as valor_enviado,
    quantidade_pagador_pf + quantidade_pagador_pj as quantidade_enviada,
    valor_recebedor_pf + valor_recebedor_pj as valor_recebido,
    quantidade_recebedor_pf + quantidade_recebedor_pj as quantidade_recebida
from pix_intermediate.int_transacoes_municipio;

CREATE OR REPLACE VIEW pix_checks.cur_pix_dispute_not_null AS
-- A current dispute names a payment, a reason, and a status.

select
    id
from pix_marts.cur_pix_dispute
where id is null
    or transaction_id is null
    or reason is null
    or status is null
    or opened_at is null;

CREATE OR REPLACE VIEW pix_checks.cur_pix_dispute_references AS
-- A dispute that outlived its payment is a broken merge, not an open case.

select
    dispute.id as dispute_id,
    dispute.transaction_id
from pix_marts.cur_pix_dispute as dispute
left join pix_marts.cur_pix_transaction as payment
    on dispute.transaction_id = payment.id
where payment.id is null;

CREATE OR REPLACE VIEW pix_checks.cur_pix_dispute_unique AS
-- One current row per dispute.

select
    id,
    count(*) as rows
from pix_marts.cur_pix_dispute
group by id
having count(*) > 1;

CREATE OR REPLACE VIEW pix_checks.cur_pix_key_not_null AS
-- A current key can be joined to the institution and municipality dimensions.

select
    id
from pix_marts.cur_pix_key
where id is null
    or key_type is null
    or key_value is null
    or person_type is null
    or ispb is null
    or length(ispb) <> 8
    or municipio_ibge is null
    or status is null;

CREATE OR REPLACE VIEW pix_checks.cur_pix_key_unique AS
-- One current row per PIX key.

select
    id,
    count(*) as rows
from pix_marts.cur_pix_key
group by id
having count(*) > 1;

CREATE OR REPLACE VIEW pix_checks.cur_pix_transaction_not_null AS
-- A current transaction keeps the codes the warehouse dimensions use.

select
    id
from pix_marts.cur_pix_transaction
where id is null
    or end_to_end_id is null
    or amount is null
    or payer_ispb is null
    or length(payer_ispb) <> 8
    or receiver_ispb is null
    or length(receiver_ispb) <> 8
    or municipio_ibge is null
    or forma_iniciacao is null
    or direction is null
    or status is null;

CREATE OR REPLACE VIEW pix_checks.cur_pix_transaction_unique AS
-- One current row per operational transaction.

select
    id,
    count(*) as rows
from pix_marts.cur_pix_transaction
group by id
having count(*) > 1;

CREATE OR REPLACE VIEW pix_checks.dim_instituicao_one_name AS
-- The latest snapshot for an ISPB must carry one name and one segment.
-- The type-1 dimension would otherwise hide a clash.

with latest as (
    select
        ispb,
        max(ano_mes) as ano_mes
    from pix_intermediate.int_chaves_pix
    group by ispb
)
select
    chaves.ispb,
    count(distinct chaves.nome) as nomes,
    count(distinct chaves.segmento) as segmentos
from pix_intermediate.int_chaves_pix as chaves
inner join latest
    on chaves.ispb = latest.ispb
    and chaves.ano_mes = latest.ano_mes
group by chaves.ispb
having count(distinct chaves.nome) > 1
    or count(distinct chaves.segmento) > 1;

CREATE OR REPLACE VIEW pix_checks.dim_keys_not_null AS
select 'dim_tempo.ano_mes' as column_name
from pix_marts.dim_tempo
where ano_mes is null
union all
select 'dim_municipio.municipio_ibge'
from pix_marts.dim_municipio
where municipio_ibge is null
union all
select 'dim_municipio.nome'
from pix_marts.dim_municipio
where nome is null
union all
select 'dim_natureza.codigo'
from pix_marts.dim_natureza
where codigo is null
union all
select 'dim_forma_iniciacao.codigo'
from pix_marts.dim_forma_iniciacao
where codigo is null
union all
select 'dim_finalidade.codigo'
from pix_marts.dim_finalidade
where codigo is null
union all
select 'dim_faixa_idade.codigo'
from pix_marts.dim_faixa_idade
where codigo is null
union all
select 'dim_tipo_pessoa.codigo'
from pix_marts.dim_tipo_pessoa
where codigo is null
union all
select 'dim_regiao.codigo'
from pix_marts.dim_regiao
where codigo is null
union all
select 'dim_tipo_chave.codigo'
from pix_marts.dim_tipo_chave
where codigo is null
union all
select 'dim_instituicao.ispb'
from pix_marts.dim_instituicao
where ispb is null;

CREATE OR REPLACE VIEW pix_checks.dim_keys_unique AS
select 'dim_tempo' as dimension_name, cast(ano_mes as varchar) as key_value, count(*) as rows
from pix_marts.dim_tempo
group by ano_mes
having count(*) > 1
union all
select 'dim_municipio', cast(municipio_ibge as varchar), count(*)
from pix_marts.dim_municipio
group by municipio_ibge
having count(*) > 1
union all
select 'dim_natureza', codigo, count(*)
from pix_marts.dim_natureza
group by codigo
having count(*) > 1
union all
select 'dim_forma_iniciacao', codigo, count(*)
from pix_marts.dim_forma_iniciacao
group by codigo
having count(*) > 1
union all
select 'dim_finalidade', codigo, count(*)
from pix_marts.dim_finalidade
group by codigo
having count(*) > 1
union all
select 'dim_faixa_idade', codigo, count(*)
from pix_marts.dim_faixa_idade
group by codigo
having count(*) > 1
union all
select 'dim_tipo_pessoa', codigo, count(*)
from pix_marts.dim_tipo_pessoa
group by codigo
having count(*) > 1
union all
select 'dim_regiao', codigo, count(*)
from pix_marts.dim_regiao
group by codigo
having count(*) > 1
union all
select 'dim_tipo_chave', codigo, count(*)
from pix_marts.dim_tipo_chave
group by codigo
having count(*) > 1
union all
select 'dim_instituicao', ispb, count(*)
from pix_marts.dim_instituicao
group by ispb
having count(*) > 1;

CREATE OR REPLACE VIEW pix_checks.dim_municipio_nao_informado AS
-- A raw municipality row with a null IBGE code has to survive as the
-- explicit "Não informado" member (municipio_ibge 0). Dropping it fails
-- this check.

select pix_staging.ano_mes
from pix_staging.stg_transacoes_pix_municipio as staging
where pix_staging.municipio_ibge is null
    and not exists (
        select 1
        from pix_marts.dim_municipio as dim
        where dim.municipio_ibge = 0
            and dim.nome = 'Não informado'
    );

CREATE OR REPLACE VIEW pix_checks.fct_chaves_pix_non_negative AS
select
    ano_mes,
    ispb,
    tipo_chave,
    quantidade_chaves
from pix_marts.fct_chaves_pix
where quantidade_chaves < 0;

CREATE OR REPLACE VIEW pix_checks.fct_chaves_pix_not_null AS
select 'ano_mes' as column_name
from pix_marts.fct_chaves_pix
where ano_mes is null
union all
select 'data_referencia'
from pix_marts.fct_chaves_pix
where data_referencia is null
union all
select 'ispb'
from pix_marts.fct_chaves_pix
where ispb is null
union all
select 'natureza_usuario'
from pix_marts.fct_chaves_pix
where natureza_usuario is null
union all
select 'tipo_chave'
from pix_marts.fct_chaves_pix
where tipo_chave is null
union all
select 'quantidade_chaves'
from pix_marts.fct_chaves_pix
where quantidade_chaves is null;

CREATE OR REPLACE VIEW pix_checks.fct_chaves_pix_references AS
select 'ano_mes' as key_name, cast(fct.ano_mes as varchar) as key_value
from pix_marts.fct_chaves_pix as fct
left join pix_marts.dim_tempo as dim
    on fct.ano_mes = dim.ano_mes
where dim.ano_mes is null
union all
select 'ispb', fct.ispb
from pix_marts.fct_chaves_pix as fct
left join pix_marts.dim_instituicao as dim
    on fct.ispb = dim.ispb
where dim.ispb is null
union all
select 'tipo_chave', fct.tipo_chave
from pix_marts.fct_chaves_pix as fct
left join pix_marts.dim_tipo_chave as dim
    on fct.tipo_chave = dim.codigo
where dim.codigo is null
union all
select 'natureza_usuario', fct.natureza_usuario
from pix_marts.fct_chaves_pix as fct
left join pix_marts.dim_tipo_pessoa as dim
    on fct.natureza_usuario = dim.codigo
where dim.codigo is null;

CREATE OR REPLACE VIEW pix_checks.fct_chaves_pix_unique_grain AS
-- Grain: one row per snapshot month, ISPB, user nature, and key type.

select
    ano_mes,
    ispb,
    natureza_usuario,
    tipo_chave,
    count(*) as rows
from pix_marts.fct_chaves_pix
group by
    ano_mes,
    ispb,
    natureza_usuario,
    tipo_chave
having count(*) > 1;

CREATE OR REPLACE VIEW pix_checks.fct_transacoes_mensal_non_negative AS
select
    ano_mes,
    natureza,
    valor,
    quantidade
from pix_marts.fct_transacoes_mensal
where valor < 0
    or quantidade < 0;

CREATE OR REPLACE VIEW pix_checks.fct_transacoes_mensal_not_null AS
select 'ano_mes' as column_name
from pix_marts.fct_transacoes_mensal
where ano_mes is null
union all
select 'pagador_tipo_pessoa'
from pix_marts.fct_transacoes_mensal
where pagador_tipo_pessoa is null
union all
select 'recebedor_tipo_pessoa'
from pix_marts.fct_transacoes_mensal
where recebedor_tipo_pessoa is null
union all
select 'pagador_regiao'
from pix_marts.fct_transacoes_mensal
where pagador_regiao is null
union all
select 'recebedor_regiao'
from pix_marts.fct_transacoes_mensal
where recebedor_regiao is null
union all
select 'pagador_faixa_idade'
from pix_marts.fct_transacoes_mensal
where pagador_faixa_idade is null
union all
select 'recebedor_faixa_idade'
from pix_marts.fct_transacoes_mensal
where recebedor_faixa_idade is null
union all
select 'forma_iniciacao'
from pix_marts.fct_transacoes_mensal
where forma_iniciacao is null
union all
select 'natureza'
from pix_marts.fct_transacoes_mensal
where natureza is null
union all
select 'finalidade'
from pix_marts.fct_transacoes_mensal
where finalidade is null
union all
select 'valor'
from pix_marts.fct_transacoes_mensal
where valor is null
union all
select 'quantidade'
from pix_marts.fct_transacoes_mensal
where quantidade is null;

CREATE OR REPLACE VIEW pix_checks.fct_transacoes_mensal_references AS
select 'ano_mes' as key_name, cast(fct.ano_mes as varchar) as key_value
from pix_marts.fct_transacoes_mensal as fct
left join pix_marts.dim_tempo as dim
    on fct.ano_mes = dim.ano_mes
where dim.ano_mes is null
union all
select 'natureza', fct.natureza
from pix_marts.fct_transacoes_mensal as fct
left join pix_marts.dim_natureza as dim
    on fct.natureza = dim.codigo
where dim.codigo is null
union all
select 'forma_iniciacao', fct.forma_iniciacao
from pix_marts.fct_transacoes_mensal as fct
left join pix_marts.dim_forma_iniciacao as dim
    on fct.forma_iniciacao = dim.codigo
where dim.codigo is null
union all
select 'finalidade', fct.finalidade
from pix_marts.fct_transacoes_mensal as fct
left join pix_marts.dim_finalidade as dim
    on fct.finalidade = dim.codigo
where dim.codigo is null
union all
select 'pagador_tipo_pessoa', fct.pagador_tipo_pessoa
from pix_marts.fct_transacoes_mensal as fct
left join pix_marts.dim_tipo_pessoa as dim
    on fct.pagador_tipo_pessoa = dim.codigo
where dim.codigo is null
union all
select 'recebedor_tipo_pessoa', fct.recebedor_tipo_pessoa
from pix_marts.fct_transacoes_mensal as fct
left join pix_marts.dim_tipo_pessoa as dim
    on fct.recebedor_tipo_pessoa = dim.codigo
where dim.codigo is null
union all
select 'pagador_regiao', fct.pagador_regiao
from pix_marts.fct_transacoes_mensal as fct
left join pix_marts.dim_regiao as dim
    on fct.pagador_regiao = dim.codigo
where dim.codigo is null
union all
select 'recebedor_regiao', fct.recebedor_regiao
from pix_marts.fct_transacoes_mensal as fct
left join pix_marts.dim_regiao as dim
    on fct.recebedor_regiao = dim.codigo
where dim.codigo is null
union all
select 'pagador_faixa_idade', fct.pagador_faixa_idade
from pix_marts.fct_transacoes_mensal as fct
left join pix_marts.dim_faixa_idade as dim
    on fct.pagador_faixa_idade = dim.codigo
where dim.codigo is null
union all
select 'recebedor_faixa_idade', fct.recebedor_faixa_idade
from pix_marts.fct_transacoes_mensal as fct
left join pix_marts.dim_faixa_idade as dim
    on fct.recebedor_faixa_idade = dim.codigo
where dim.codigo is null;

CREATE OR REPLACE VIEW pix_checks.fct_transacoes_mensal_unique_grain AS
-- Grain: month x payer/receiver person type, region, and age band x
-- initiation form x natureza x finalidade.

select
    ano_mes,
    pagador_tipo_pessoa,
    recebedor_tipo_pessoa,
    pagador_regiao,
    recebedor_regiao,
    pagador_faixa_idade,
    recebedor_faixa_idade,
    forma_iniciacao,
    natureza,
    finalidade,
    count(*) as rows
from pix_marts.fct_transacoes_mensal
group by
    ano_mes,
    pagador_tipo_pessoa,
    recebedor_tipo_pessoa,
    pagador_regiao,
    recebedor_regiao,
    pagador_faixa_idade,
    recebedor_faixa_idade,
    forma_iniciacao,
    natureza,
    finalidade
having count(*) > 1;

CREATE OR REPLACE VIEW pix_checks.fct_transacoes_municipio_non_negative AS
select
    ano_mes,
    municipio_ibge
from pix_marts.fct_transacoes_municipio
where valor_pagador_pf < 0
    or valor_pagador_pj < 0
    or valor_recebedor_pf < 0
    or valor_recebedor_pj < 0
    or quantidade_pagador_pf < 0
    or quantidade_pagador_pj < 0
    or quantidade_recebedor_pf < 0
    or quantidade_recebedor_pj < 0
    or quantidade_pessoas_pagador_pf < 0
    or quantidade_pessoas_pagador_pj < 0
    or quantidade_pessoas_recebedor_pf < 0
    or quantidade_pessoas_recebedor_pj < 0
    or valor_enviado < 0
    or valor_recebido < 0
    or quantidade_enviada < 0
    or quantidade_recebida < 0;

CREATE OR REPLACE VIEW pix_checks.fct_transacoes_municipio_not_null AS
select 'ano_mes' as column_name
from pix_marts.fct_transacoes_municipio
where ano_mes is null
union all
select 'municipio_ibge'
from pix_marts.fct_transacoes_municipio
where municipio_ibge is null
union all
select 'valor_enviado'
from pix_marts.fct_transacoes_municipio
where valor_enviado is null
union all
select 'valor_recebido'
from pix_marts.fct_transacoes_municipio
where valor_recebido is null
union all
select 'quantidade_enviada'
from pix_marts.fct_transacoes_municipio
where quantidade_enviada is null
union all
select 'quantidade_recebida'
from pix_marts.fct_transacoes_municipio
where quantidade_recebida is null;

CREATE OR REPLACE VIEW pix_checks.fct_transacoes_municipio_references AS
select 'ano_mes' as key_name, cast(fct.ano_mes as varchar) as key_value
from pix_marts.fct_transacoes_municipio as fct
left join pix_marts.dim_tempo as dim
    on fct.ano_mes = dim.ano_mes
where dim.ano_mes is null
union all
select 'municipio_ibge', cast(fct.municipio_ibge as varchar)
from pix_marts.fct_transacoes_municipio as fct
left join pix_marts.dim_municipio as dim
    on fct.municipio_ibge = dim.municipio_ibge
where dim.municipio_ibge is null;

CREATE OR REPLACE VIEW pix_checks.fct_transacoes_municipio_unique_grain AS
-- Grain: one row per month and municipality, including ibge 0.

select
    ano_mes,
    municipio_ibge,
    count(*) as rows
from pix_marts.fct_transacoes_municipio
group by
    ano_mes,
    municipio_ibge
having count(*) > 1;
